def trace_block_shapes(B, T, n_embd, n_head):
    if n_embd % n_head != 0:
        raise ValueError("n_embd must be divisible by n_head")
    hs = n_embd // n_head
    return {
        "input": (B, T, n_embd),
        "qkv_per_head": (B, T, hs),
        "scores": (B, T, T),
        "mha_concat": (B, T, n_embd),
        "mha_out": (B, T, n_embd),
        "ffn_hidden": (B, T, 4 * n_embd),
        "block_out": (B, T, n_embd),
    }
